#pragma once

#include "CoreMinimal.h"
#include "GameFramework/GameModeBase.h"
#include "ArenaGameMode.generated.h"

class UArenaHud;
class UArenaPalette;
class UArenaScoreTracker;
struct FArenaStats;

UCLASS()
class PIXELARENA_API AArenaGameMode : public AGameModeBase
{
	GENERATED_BODY()

public:
	virtual void BeginPlay() override;
	virtual void EndPlay(const EEndPlayReason::Type Reason) override;

	void OnGoalScored(int32 TeamIndex);

private:
	UPROPERTY()
	TObjectPtr<UArenaHud> Hud;

	UPROPERTY()
	TObjectPtr<UArenaPalette> Palette;

	UPROPERTY()
	TObjectPtr<UArenaScoreTracker> ScoreTracker;

	// Plain C++ data owned by this class, freed in EndPlay.
	FArenaStats* Stats = nullptr;
};


--- result.json ---
{
  "crash_cause": "UArenaScoreTracker is created with NewObject but held only in an unreflected raw pointer, so garbage collection can reclaim it; OnGoalScored then calls AddPoints on the stale pointer. The log's GC event before the goal and access violation in AddPoints support this. Fix: store it in a UPROPERTY TObjectPtr so Unreal's GC retains it.",
  "no_colors_cause": "The palette asset at /Game/Data/Palettes/DA_Primary is loaded by a runtime hard-coded path but its directory was not configured to cook; the packaged log confirms the package is missing and fallback gray is used. Fix: add /Game/Data/Palettes to DirectoriesToAlwaysCook."
}
